sys_variable_value.value:
(function execute(inputs, outputs) {
 var payload = JSON.parse(inputs.payload);
 
    // Default sprint object
    var sprint = {
        name: 'Backlog',
        state: 'NA',
        boardId: 'NA',
        goal:'NA',
        startDate:'NA',
        endDate: 'NA',
    };
 
    // Check whether sprint exists
    if (payload.issue &&
        payload.issue.fields &&
        payload.issue.fields.customfield_10020 &&
        payload.issue.fields.customfield_10020.length > 0) {
 
        var s = payload.issue.fields.customfield_10020[0];
    sprint = {
            id: s.id,
            name: s.name,
            state: s.state,
            boardId: s.boardId,
            goal: s.goal,
            startDate: s.startDate,
            endDate: s.endDate
        };
    }
    var details = {
        webhook_event: payload.webhookEvent,
        issue: {
            id: payload.issue.id,
            key: payload.issue.key,
            type: payload.issue.fields.issuetype.name
        },
        project: {
            id: payload.issue.fields.project.id,
            key: payload.issue.fields.project.key,
            name: payload.issue.fields.project.name
        },
        sprint: sprint
    };
    outputs.sprint_details = JSON.stringify(details);
    outputs.story_id1 = payload.issue.key;
})(inputs, outputs)

